<?php
namespace Database\Factories; use App\Models\Article; use Illuminate\Database\Eloquent\Factories\Factory; class ArticleFactory extends Factory { protected $model=Article::class; public function definition():array{return ['title'=>fake()->sentence(4),'slug'=>fake()->unique()->slug(),'excerpt'=>fake()->paragraph(),'body'=>fake()->paragraphs(4,true),'status'=>'draft','is_featured'=>false,'display_order'=>1,'robots_index'=>true,'robots_follow'=>true];} public function published():static{return $this->state(fn()=>['status'=>'published','published_at'=>now()->subMinute()]);} public function scheduledDue():static{return $this->state(fn()=>['status'=>'scheduled','scheduled_for'=>now()->subMinute()]);} }
